  /* ---------------- rutas ---------------- */
  function get(ruta) {
    return ruta.split(".").reduce(function (o, k) { return (o == null) ? undefined : o[k]; }, D);
  }
  function set(ruta, valor) {
    var partes = ruta.split(".");
